def transform(grid):
    out=[row[:] for row in grid]
    bg=max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    motif=[[3,5,3],[bg,5,3],[bg,bg,3]]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==8:
                for dr in range(3):
                    for dc in range(3):
                        rr,cc=r-1+dr,c-1+dc
                        if 0<=rr<len(out) and 0<=cc<len(out[0]) and motif[dr][dc]!=bg:
                            out[rr][cc]=motif[dr][dc]
    return out
